/bin/bash -lc "cat > /tmp/build_lab_dns.py <<'PY'
from pathlib import Path
import re
p=Path('.')
zones=['.', 'com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it']
ips={i:re.search(r'inet (10\\.\\d+\\.\\d+\\.\\d+)/24', (p/f'pc{i}.startup').read_text()).group(1) for i in range(1,41)}
assert len(zones)==31 and len(set(zones))==31
for i,z in enumerate(zones,1):
    base=p/f'pc{i}'/'etc'/'bind'; base.mkdir(parents=True,exist_ok=True)
    ns='ns.root.' if z=='.' else f'ns.{z}.'
    origin='.' if z=='.' else z+'.'
    lines=['"'$TTL 3600'"',f'"'$ORIGIN {origin}'"',f'@ IN SOA {ns} hostmaster.{origin} ( 2026110201 3600 900 604800 300 )',f'@ IN NS {ns}', f'ns{\".root\" if z==\".\" else \"\"} IN A {ips[i]}']
    if z"'!='"'.': lines.append(f'@ IN A {ips[i]}')
    for j,child in enumerate(zones,1):
        if child=='.': continue
        parent=child.partition('.')[2] or '.'
        if parent==z:
            label=child.split('.')[0]
            lines += [f'{label} IN NS ns.{child}.',f'ns.{child}. IN A {ips[j]}']
    if z=='example.com': lines.append(f'www IN A {ips[i]}')
    if z in ('company.com','university.edu'): lines += ['@ IN MX 10 mail.'+z+'.',f'mail IN A {ips[i]}']
    (base/'db.zone').write_text('\\n'.join(lines)+'\\n')
    (base/'named.conf').write_text('''options {
    directory \"/etc/bind\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    allow-query { any; };
    recursion no;
    dnssec-validation no;
    pid-file \"/run/named-lab.pid\";
};
zone \"%s\" { type primary; file \"/etc/bind/db.zone\"; };
'''%z)
base=p/'pc32'/'etc'/'bind'; base.mkdir(parents=True,exist_ok=True)
(base/'root.hints').write_text(f'. 3600 IN NS ns.root.\\nns.root. 3600 IN A {ips[1]}\\n')
(base/'named.conf').write_text('''options {
    directory \"/etc/bind\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    allow-query { any; };
    allow-recursion { 10.15.0.0/16; 127.0.0.1; };
    allow-query-cache { 10.15.0.0/16; 127.0.0.1; };
    recursion yes;
    dnssec-validation no;
    empty-zones-enable no;
    pid-file \"/run/named-lab.pid\";
};
zone \".\" { type hint; file \"/etc/bind/root.hints\"; };
''')
for i in range(1,41):
    path=p/f'pc{i}.startup'; contents=path.read_text(); contents+=f'\\n# Use the laboratory recursive DNS server.\\nprintf \"nameserver {ips[32]}\\\\n\" > /etc/resolv.conf\\n'
    if i<=32: contents+='\\n# Start the laboratory DNS service.\\nnamed -4 -c /etc/bind/named.conf -g > /var/log/named-lab.log 2>&1 &\\n'
    path.write_text(contents)
print('resolver',ips[32], 'root',ips[1])
PY
python3 /tmp/build_lab_dns.py"

